async function sendVerificationEmail(email, code) {
  try {
    const config = await getSmtpConfig();
    const nodemailer = await Promise.resolve().then(() => __toESM(require_nodemailer(), 1));
    const transporter = nodemailer.default.createTransport(config);
    const template = config.emailTemplate || getEmailTemplate(code, email);
    const mailOptions = {
      from: {
        name: "FireflyCloud",
        address: config.auth.user
      },
      to: email,
      subject: "\u3010FireflyCloud\u3011\u90AE\u7BB1\u9A8C\u8BC1\u7801",
      html: template.replace(/\{\{CODE\}\}/g, code),
      text: `\u60A8\u7684 FireflyCloud \u90AE\u7BB1\u9A8C\u8BC1\u7801\u662F\uFF1A${code}\uFF0C\u6709\u6548\u671F10\u5206\u949F\u3002\u8BF7\u52FF\u5C06\u9A8C\u8BC1\u7801\u5206\u4EAB\u7ED9\u4ED6\u4EBA\u3002`
    };
    const result = await transporter.sendMail(mailOptions);
    logger3.email(email, "\u3010FireflyCloud\u3011\u90AE\u7BB1\u9A8C\u8BC1\u7801", true);
    logger3.info(`\u90AE\u4EF6\u53D1\u9001\u6210\u529F: ${result.messageId}`);
    return true;
  } catch (error) {
    logger3.email(email, "\u3010FireflyCloud\u3011\u90AE\u7BB1\u9A8C\u8BC1\u7801", false, error instanceof Error ? error : new Error(String(error)));
    logger3.error("\u90AE\u4EF6\u53D1\u9001\u5931\u8D25:", error);
    return false;
  }
}

// src/services/quota.ts
init_db2();
init_schema();
init_drizzle_orm();
init_logger2();
init_nanoid();

class QuotaService {
  static async checkUserQuota(userId, additionalSize) {
    try {
      const quota = await db2.select().from(userQuotas).where(eq(userQuotas.userId, userId)).get();
      if (!quota) {
        const user = await db2.select().from(users).where(eq(users.id, userId)).get();
        if (!user) {
          return {
            allowed: false,
            currentUsed: 0,
            maxStorage: 0,
            availableSpace: 0,
            error: "User not found"
          };
        }
        const newQuota = await this.createUserQuota(userId, user.role);
        if (!newQuota) {
          return {
            allowed: false,
            currentUsed: 0,
            maxStorage: 0,
            availableSpace: 0,
            error: "Failed to create user quota"
          };
        }
        return this.checkUserQuota(userId, additionalSize);
      }
      const userFiles = await db2.select().from(files).where(eq(files.userId, userId)).all();
      logger3.debug(`\u7528\u6237 ${userId} \u914D\u989D\u68C0\u67E5: \u627E\u5230 ${userFiles.length} \u4E2A\u6587\u4EF6`);
      let localStorage2 = 0;
      let localCount = 0;
      userFiles.forEach((file) => {
        if (file.storageType === "local") {
          localStorage2 += file.size;
          localCount++;
        }
      });
      let r2Storage = 0;
      let r2Count = 0;
      const { storageConfig: storageConfig2 } = await Promise.resolve().then(() => (init_schema(), exports_schema));
      const config4 = await db2.select().from(storageConfig2).get();
      if (config4 && (config4.storageType === "r2" || config4.enableMixedMode) && config4.r2Endpoint) {
        try {
          const { StorageService: StorageService2 } = await Promise.resolve().then(() => (init_storage2(), exports_storage));
          const storageService = new StorageService2(config4);
          const r2Stats = await storageService.calculateR2StorageUsage();
          if (!r2Stats.error) {
            r2Storage = r2Stats.totalSize;
            r2Count = r2Stats.totalFiles;
            logger3.debug(`\u7528\u6237 ${userId} R2\u5B9E\u9645\u4F7F\u7528\u91CF: ${r2Count} \u4E2A\u6587\u4EF6\uFF0C${r2Storage} \u5B57\u8282`);
          } else {
            logger3.warn(`\u7528\u6237 ${userId} R2\u5B58\u50A8\u67E5\u8BE2\u5931\u8D25: ${r2Stats.error}`);
          }
        } catch (error) {
          logger3.error(`\u7528\u6237 ${userId} R2\u5B58\u50A8\u67E5\u8BE2\u5F02\u5E38:`, error);
        }
      }
      let oneDriveStorage = 0;
      let oneDriveCount = 0;
      userFiles.forEach((file) => {
        if (file.storageType === "onedrive") {
          oneDriveStorage += file.size;
          oneDriveCount++;
        }
      });
      const currentUsed = localStorage2 + r2Storage + oneDriveStorage;
      const maxStorage = quota.customQuota || quota.maxStorage;
      const availableSpace = maxStorage - currentUsed;
      const allowed = availableSpace >= additionalSize;
      if (currentUsed !== quota.usedStorage) {
        await db2.update(userQuotas).set({
          usedStorage: currentUsed,
          updatedAt: Date.now()
        }).where(eq(userQuotas.userId, userId));
        logger3.database("UPDATE", "user_quotas");
      } else {
        logger3.debug(`\u7528\u6237 ${userId} \u914D\u989D\u6570\u636E\u4E00\u81F4: ${currentUsed}`);
      }
      return {
        allowed,
        currentUsed,
        maxStorage,
        availableSpace
      };
    } catch (error) {
      logger3.error("\u68C0\u67E5\u7528\u6237\u914D\u989D\u5931\u8D25:", error);
      return {
        allowed: false,
        currentUsed: 0,
        maxStorage: 0,
        availableSpace: 0,
        error: error instanceof Error ? error.message : "Unknown error"
      };
    }
  }
  static async updateUserStorage(userId, sizeChange) {
    try {
      const quota = await db2.select().from(userQuotas).where(eq(userQuotas.userId, userId)).get();
      if (!quota) {
        logger3.warn(`\u7528\u6237 ${userId} \u6CA1\u6709\u914D\u989D\u8BB0\u5F55\uFF0C\u65E0\u6CD5\u66F4\u65B0\u5B58\u50A8\u4F7F\u7528\u91CF`);
        return false;
      }
      const newUsedStorage = Math.max(0, quota.usedStorage + sizeChange);
      await db2.update(userQuotas).set({
        usedStorage: newUsedStorage,
        updatedAt: Date.now()
      }).where(eq(userQuotas.userId, userId));
      logger3.database("UPDATE", "user_quotas");
      logger3.debug(`\u7528\u6237 ${userId} \u5B58\u50A8\u4F7F\u7528\u91CF\u66F4\u65B0: ${quota.usedStorage} -> ${newUsedStorage} (\u53D8\u5316: ${sizeChange})`);
      return true;
    } catch (error) {
      logger3.error("\u66F4\u65B0\u7528\u6237\u5B58\u50A8\u4F7F\u7528\u91CF\u5931\u8D25:", error);
      return false;
    }
  }
  static async recalculateUserStorage(userId) {
    try {
      const quota = await db2.select().from(userQuotas).where(eq(userQuotas.userId, userId)).get();
      if (!quota) {
        return {
          success: false,
          oldUsed: 0,
          newUsed: 0,
          fileCount: 0,
          localStorage: 0,
          r2Storage: 0,
          localFiles: 0,
          r2Files: 0,
          error: "User quota not found"
        };
      }
      const userFiles = await db2.select().from(files).where(eq(files.userId, userId)).all();
      let localStorage2 = 0;
      let r2Storage = 0;
      let oneDriveStorage = 0;
      let localFiles = 0;
      let r2Files = 0;
      let oneDriveFiles = 0;
      userFiles.forEach((file) => {
        if (file.storageType === "local") {
          localStorage2 += file.size;
          localFiles++;
        } else if (file.storageType === "r2") {
          r2Storage += file.size;
          r2Files++;
        } else if (file.storageType === "onedrive") {
          oneDriveStorage += file.size;
          oneDriveFiles++;
        }
      });
      const actualUsedStorage = localStorage2 + r2Storage + oneDriveStorage;
      const oldUsed = quota.usedStorage;
      await db2.update(userQuotas).set({
        usedStorage: actualUsedStorage,
        updatedAt: Date.now()
      }).where(eq(userQuotas.userId, userId));
      logger3.database("UPDATE", "user_quotas");
      logger3.info(`\u7528\u6237 ${userId} \u5B58\u50A8\u4F7F\u7528\u91CF\u91CD\u65B0\u8BA1\u7B97: ${oldUsed} -> ${actualUsedStorage} (\u603B\u8BA1: ${userFiles.length} \u4E2A\u6587\u4EF6, \u672C\u5730: ${localFiles} \u4E2A/${localStorage2} \u5B57\u8282, R2: ${r2Files} \u4E2A/${r2Storage} \u5B57\u8282, OneDrive: ${oneDriveFiles} \u4E2A/${oneDriveStorage} \u5B57\u8282)`);
      return {
        success: true,
        oldUsed,
        newUsed: actualUsedStorage,
        fileCount: userFiles.length,
        localStorage: localStorage2,
        r2Storage,
        localFiles,
        r2Files
      };
    } catch (error) {
      logger3.error("\u91CD\u65B0\u8BA1\u7B97\u7528\u6237\u5B58\u50A8\u4F7F\u7528\u91CF\u5931\u8D25:", error);
      return {
        success: false,
        oldUsed: 0,
        newUsed: 0,
        fileCount: 0,
        localStorage: 0,
        r2Storage: 0,
        localFiles: 0,
        r2Files: 0,
        error: error instanceof Error ? error.message : "Unknown error"
      };
    }
  }
  static async createUserQuota(userId, userRole) {
    try {
      const roleConfig = await db2.select().from(roleQuotaConfig).where(eq(roleQuotaConfig.role, userRole)).get();
      const defaultQuota = roleConfig ? roleConfig.defaultQuota : userRole === "admin" ? 10737418240 : 1073741824;
      const userFiles = await db2.select().from(files).where(eq(files.userId, userId)).all();
      let localStorage2 = 0;
      let r2Storage = 0;
      userFiles.forEach((file) => {
        if (file.storageType === "local") {
          localStorage2 += file.size;
        } else if (file.storageType === "r2") {
          r2Storage += file.size;
        }
      });
      const totalUsedStorage = localStorage2 + r2Storage;
      const quotaId = nanoid();
      await db2.insert(userQuotas).values({
        id: quotaId,
        userId,
        maxStorage: defaultQuota,
        usedStorage: totalUsedStorage,
        role: userRole,
        createdAt: Date.now(),
        updatedAt: Date.now()
      });
      logger3.database("INSERT", "user_quotas");
      logger3.info(`\u4E3A\u7528\u6237 ${userId} (${userRole}) \u521B\u5EFA\u914D\u989D\u8BB0\u5F55: ${Math.round(defaultQuota / 1024 / 1024 / 1024)}GB\uFF0C\u5F53\u524D\u4F7F\u7528: ${Math.round(totalUsedStorage / 1024 / 1024)}MB (\u672C\u5730: ${Math.round(localStorage2 / 1024 / 1024)}MB, R2: ${Math.round(r2Storage / 1024 / 1024)}MB)`);
      return true;
    } catch (error) {
      logger3.error("\u521B\u5EFA\u7528\u6237\u914D\u989D\u8BB0\u5F55\u5931\u8D25:", error);
      return false;
    }
  }
  static async getUserQuota(userId) {
    try {
      const quota = await db2.select().from(userQuotas).where(eq(userQuotas.userId, userId)).get();
      if (!quota) {
        return null;
      }
      const userFiles = await db2.select().from(files).where(eq(files.userId, userId)).all();
      logger3.debug(`\u7528\u6237 ${userId} \u6587\u4EF6\u67E5\u8BE2\u7ED3\u679C: \u627E\u5230 ${userFiles.length} \u4E2A\u6587\u4EF6`);
      let localStorage2 = 0;
      let localCount = 0;
      userFiles.forEach((file) => {
        logger3.debug(`\u6587\u4EF6: ${file.originalName}, \u5927\u5C0F: ${file.size}, \u5B58\u50A8\u7C7B\u578B: ${file.storageType}`);
        if (file.storageType === "local") {
          localStorage2 += file.size;
          localCount++;
        }
      });
      let r2Storage = 0;
      let r2Count = 0;
      const { storageConfig: storageConfig2 } = await Promise.resolve().then(() => (init_schema(), exports_schema));
      const config4 = await db2.select().from(storageConfig2).get();
      if (config4 && (config4.storageType === "r2" || config4.enableMixedMode) && config4.r2Endpoint) {
        try {
          const { StorageService: StorageService2 } = await Promise.resolve().then(() => (init_storage2(), exports_storage));
          const storageService = new StorageService2(config4);
          const r2Stats = await storageService.calculateR2StorageUsage();
          if (!r2Stats.error) {
            r2Storage = r2Stats.totalSize;
            r2Count = r2Stats.totalFiles;
            logger3.debug(`\u7528\u6237 ${userId} R2\u5B9E\u9645\u4F7F\u7528\u91CF: ${r2Count} \u4E2A\u6587\u4EF6\uFF0C${r2Storage} \u5B57\u8282`);
          } else {
            logger3.warn(`\u7528\u6237 ${userId} R2\u5B58\u50A8\u67E5\u8BE2\u5931\u8D25: ${r2Stats.error}`);
          }
        } catch (error) {
          logger3.error(`\u7528\u6237 ${userId} R2\u5B58\u50A8\u67E5\u8BE2\u5F02\u5E38:`, error);
        }
      }
      let oneDriveStorage = 0;
      let oneDriveCount = 0;
      userFiles.forEach((file) => {
        if (file.storageType === "onedrive") {
          oneDriveStorage += file.size;
          oneDriveCount++;
        }
      });
      const actualUsedStorage = localStorage2 + r2Storage + oneDriveStorage;
      const maxStorage = quota.customQuota || quota.maxStorage;
      const availableSpace = maxStorage - actualUsedStorage;
      if (actualUsedStorage !== quota.usedStorage) {
        logger3.info(`\u7528\u6237 ${userId} \u914D\u989D\u6570\u636E\u4E0D\u4E00\u81F4\uFF0C\u66F4\u65B0: ${quota.usedStorage} -> ${actualUsedStorage}`);
        await db2.update(userQuotas).set({
          usedStorage: actualUsedStorage,
          updatedAt: Date.now()
        }).where(eq(userQuotas.userId, userId));
        logger3.database("UPDATE", "user_quotas");
      } else {
        logger3.debug(`\u7528\u6237 ${userId} \u914D\u989D\u6570\u636E\u4E00\u81F4: ${actualUsedStorage}`);
      }
      return {
        maxStorage,
        usedStorage: actualUsedStorage,
        availableSpace,
        role: quota.role,
        customQuota: quota.customQuota || undefined
      };
    } catch (error) {
      logger3.error("\u83B7\u53D6\u7528\u6237\u914D\u989D\u4FE1\u606F\u5931\u8D25:", error);
      return {
        maxStorage: 0,
        usedStorage: 0,
        availableSpace: 0,
        role: "user",
        error: error instanceof Error ? error.message : "Unknown error"
      };
    }
  }
  static formatFileSize(bytes) {
    if (bytes === 0)
      return "0 \u5B57\u8282";
    const k4 = 1024;
    const sizes = ["\u5B57\u8282", "KB", "MB", "GB", "TB"];
    const i4 = Math.floor(Math.log(bytes) / Math.log(k4));
    return Number.parseFloat((bytes / Math.pow(k4, i4)).toFixed(2)) + " " + sizes[i4];
  }
  static getUsagePercentage(used, total) {
    if (total === 0)
      return 0;
    return Math.round(used / total * 100);
  }
}

// src/services/google-oauth.ts
init_logger2();

class GoogleOAuthService {
  config;
  constructor(config4) {
    this.config = config4;
  }
  getAuthUrl(state) {
    const params = new URLSearchParams({
      client_id: this.config.clientId,
      redirect_uri: this.config.redirectUri,
      response_type: "code",
      scope: "openid email profile",
      access_type: "offline",
      prompt: "consent"
    });
    if (state) {
      params.append("state", state);
    }
    return `https://accounts.google.com/o/oauth2/v2/auth?${params.toString()}`;
  }
  async getAccessToken(code) {
    try {
      const response = await fetch("https://oauth2.googleapis.com/token", {
        method: "POST",
        headers: {
          "Content-Type": "application/x-www-form-urlencoded"
        },
        body: new URLSearchParams({
          client_id: this.config.clientId,
          client_secret: this.config.clientSecret,
          code,
          grant_type: "authorization_code",
          redirect_uri: this.config.redirectUri
        })
      });
      if (!response.ok) {
        const error = await response.text();
        logger3.error("\u83B7\u53D6\u8C37\u6B4C\u8BBF\u95EE\u4EE4\u724C\u5931\u8D25:", error);
        throw new Error("\u83B7\u53D6\u8BBF\u95EE\u4EE4\u724C\u5931\u8D25");
      }
      return await response.json();
    } catch (error) {
      logger3.error("\u8C37\u6B4COAuth\u4EE4\u724C\u4EA4\u6362\u5931\u8D25:", error);
      throw error;
    }
  }
  async getUserInfo(accessToken) {
    try {
      const response = await fetch("https://www.googleapis.com/oauth2/v2/userinfo", {
        headers: {
          Authorization: `Bearer ${accessToken}`
        }
      });
      if (!response.ok) {
        const error = await response.text();
        logger3.error("\u83B7\u53D6\u8C37\u6B4C\u7528\u6237\u4FE1\u606F\u5931\u8D25:", error);
        throw new Error("\u83B7\u53D6\u7528\u6237\u4FE1\u606F\u5931\u8D25");
      }
      const userInfo = await response.json();
      if (!userInfo.email || !userInfo.verified_email) {
        throw new Error("\u8C37\u6B4C\u8D26\u6237\u90AE\u7BB1\u672A\u9A8C\u8BC1");
      }
      return userInfo;
    } catch (error) {
      logger3.error("\u83B7\u53D6\u8C37\u6B4C\u7528\u6237\u4FE1\u606F\u5931\u8D25:", error);
      throw error;
    }
  }
  async verifyIdToken(idToken) {
    try {
      const response = await fetch(`https://oauth2.googleapis.com/tokeninfo?id_token=${idToken}`);
      if (!response.ok) {
        throw new Error("ID\u4EE4\u724C\u9A8C\u8BC1\u5931\u8D25");
      }
      const tokenInfo = await response.json();
      if (tokenInfo.aud !== this.config.clientId) {
        throw new Error("ID\u4EE4\u724C\u5BA2\u6237\u7AEFID\u4E0D\u5339\u914D");
      }
      return tokenInfo;
    } catch (error) {
      logger3.error("\u8C37\u6B4CID\u4EE4\u724C\u9A8C\u8BC1\u5931\u8D25:", error);
      throw error;
    }
  }
}

