var uploadRoutes = new Elysia().post("/upload", async (ctx) => {
  const { body, set: set2 } = ctx;
  const { user } = ctx;
  try {
    const { file, folderId, currentR2Path } = body;
    if (!file || !(file instanceof File)) {
      logger3.warn(`\u6587\u4EF6\u4E0A\u4F20\u5931\u8D25: \u7528\u6237 ${user.userId} \u672A\u63D0\u4F9B\u6587\u4EF6`);
      set2.status = 400;
      return { error: "No file provided" };
    }
    if (folderId) {
      const folder = await db2.select().from(folders).where(and(eq(folders.id, folderId), eq(folders.userId, user.userId))).get();
      if (!folder) {
        logger3.warn(`\u6587\u4EF6\u5939\u4E0D\u5B58\u5728: ${folderId} - \u7528\u6237: ${user.userId}`);
        set2.status = 404;
        return { error: "Folder not found" };
      }
    }
    logger3.info(`\u5F00\u59CB\u4E0A\u4F20\u6587\u4EF6: ${file.name} (${file.size} bytes) \u5230\u6587\u4EF6\u5939: ${folderId || "root"} - \u7528\u6237: ${user.userId}`);
    const { assignment, strategy } = await UserStorageStrategyService.getUserEffectiveStorageStrategy(user.userId);
    let config4;
    let targetStorageType;
    let userFolder = "";
    if (assignment && strategy) {
      config4 = {
        ...strategy.config,
        storageType: strategy.type
      };
      targetStorageType = strategy.type;
      userFolder = assignment.userFolder;
      logger3.info(`\u4F7F\u7528\u7528\u6237\u5B58\u50A8\u7B56\u7565: ${strategy.name} (${strategy.type}) - \u7528\u6237\u6587\u4EF6\u5939: ${userFolder}`);
    } else {
      const globalConfig = await db2.select().from(storageConfig).get();
      if (!globalConfig) {
        logger3.error("\u5B58\u50A8\u914D\u7F6E\u672A\u627E\u5230");
        set2.status = 500;
        return { error: "Storage not configured" };
      }
      config4 = globalConfig;
      targetStorageType = globalConfig.storageType;
      logger3.info(`\u4F7F\u7528\u5168\u5C40\u5B58\u50A8\u914D\u7F6E: ${targetStorageType}`);
    }
    let r2MountPoint = null;
    if (folderId) {
      let currentFolderId = folderId;
      while (currentFolderId) {
        const mountPoint = await db2.select().from(r2MountPoints).where(and(eq(r2MountPoints.folderId, currentFolderId), eq(r2MountPoints.userId, user.userId), eq(r2MountPoints.enabled, true))).get();
        if (mountPoint) {
          r2MountPoint = mountPoint;
          targetStorageType = "r2";
          logger3.info(`\u53D1\u73B0R2\u6302\u8F7D\u70B9: ${mountPoint.mountName} -> ${mountPoint.r2Path}`);
          break;
        }
        const parentFolder = await db2.select({ parentId: folders.parentId }).from(folders).where(eq(folders.id, currentFolderId)).get();
        currentFolderId = parentFolder?.parentId;
      }
    }
    const quotaCheck = await QuotaService.checkUserQuota(user.userId, file.size);
    if (!quotaCheck.allowed) {
      logger3.warn(`\u7528\u6237 ${user.userId} \u914D\u989D\u4E0D\u8DB3: \u9700\u8981 ${file.size} \u5B57\u8282, \u53EF\u7528 ${quotaCheck.availableSpace} \u5B57\u8282`);
      set2.status = 413;
      return { error: "Storage quota exceeded", details: {
        fileSize: file.size,
        currentUsed: quotaCheck.currentUsed,
        maxStorage: quotaCheck.maxStorage,
        availableSpace: quotaCheck.availableSpace
      } };
    }
    const storageService = new StorageService(config4);
    const fileId = nanoid();
    const isOneDrive = targetStorageType === "onedrive";
    const filename = isOneDrive ? file.name : `${fileId}-${file.name}`;
    let storagePath;
    if (targetStorageType === "r2" && r2MountPoint) {
      let targetR2Path = currentR2Path || r2MountPoint.r2Path;
      const fullR2Path = targetR2Path ? `${targetR2Path}/${filename}` : filename;
      const r2Config = { ...config4, storageType: "r2" };
      const r2StorageService = new StorageService(r2Config);
      storagePath = await r2StorageService.uploadToR2Direct(file, fullR2Path);
      logger3.info(`\u6587\u4EF6\u4E0A\u4F20\u5230R2\u6302\u8F7D\u70B9: ${r2MountPoint.mountName} -> ${fullR2Path}`);
      logger3.info(`\u5F53\u524DR2\u8DEF\u5F84: ${currentR2Path || "\u672A\u6307\u5B9A\uFF0C\u4F7F\u7528\u6302\u8F7D\u70B9\u8DEF\u5F84"}`);
    } else if (userFolder && targetStorageType !== "local") {
      const userFilePath = `${userFolder}/${filename}`;
      storagePath = await storageService.uploadFileToUserFolder(file, userFilePath, user.userId);
      logger3.info(`\u6587\u4EF6\u4E0A\u4F20\u5230\u7528\u6237\u4E13\u5C5E\u6587\u4EF6\u5939: ${userFolder}/${filename}`);
    } else {
      storagePath = await storageService.uploadFile(file, filename, user.userId);
    }
    logger3.file("UPLOAD", file.name, file.size, true);
    await QuotaService.updateUserStorage(user.userId, file.size);
    await db2.insert(files).values({
      id: fileId,
      userId: user.userId,
      folderId: folderId || null,
      filename,
      originalName: file.name,
      size: file.size,
      mimeType: file.type,
      storageType: targetStorageType,
      storagePath,
      createdAt: Date.now()
    });
    return { message: "File uploaded successfully", file: {
      id: fileId,
      filename,
      originalName: file.name,
      size: file.size,
      mimeType: file.type,
      folderId: folderId || null
    } };
  } catch (error) {
    logger3.error("\u6587\u4EF6\u4E0A\u4F20\u5931\u8D25:", error);
    logger3.file("UPLOAD", body?.file?.name || "unknown", body?.file?.size, false, error instanceof Error ? error : undefined);
    set2.status = 500;
    return { error: "Upload failed" };
  }
}, {
  body: t.Object({
    file: t.File(),
    folderId: t.Optional(t.String()),
    currentR2Path: t.Optional(t.String())
  })
});

// src/routes/files/download-token.ts
init_nanoid();
init_db2();
