var strategiesRoutes = new Elysia().get("/strategies", async (ctx) => {
  const { user } = ctx;
  try {
    logger3.debug(`\u83B7\u53D6\u7528\u6237\u5B58\u50A8\u7B56\u7565: ${user.userId}`);
    const strategies = await db2.select().from(storageStrategies).all();
    const safeStrategies = strategies.map((strategy) => ({
      ...strategy,
      config: JSON.parse(strategy.config),
      createdAt: new Date(strategy.createdAt).toISOString(),
      updatedAt: new Date(strategy.updatedAt).toISOString()
    })).map((strategy) => ({
      ...strategy,
      config: {
        ...strategy.config,
        r2SecretKey: strategy.config.r2SecretKey ? "***" : undefined,
        webDavPass: strategy.config.webDavPass ? "***" : undefined,
        oneDriveClientSecret: strategy.config.oneDriveClientSecret ? "***" : undefined
      }
    }));
    logger3.info(`\u8FD4\u56DE ${safeStrategies.length} \u4E2A\u5B58\u50A8\u7B56\u7565`);
    return { strategies: safeStrategies };
  } catch (error) {
    logger3.error("\u83B7\u53D6\u5B58\u50A8\u7B56\u7565\u5931\u8D25:", error);
    return { strategies: [] };
  }
}).post("/strategies", async (ctx) => {
  const { body, set: set2 } = ctx;
  try {
    const { name, type, config: config4, clientSecret } = body;
    logger3.info(`\u521B\u5EFA\u5B58\u50A8\u7B56\u7565: ${name} (${type})`);
    const existingStrategy = await db2.select().from(storageStrategies).where(eq(storageStrategies.name, name)).get();
    if (existingStrategy) {
      set2.status = 400;
      return { error: "\u7B56\u7565\u540D\u79F0\u5DF2\u5B58\u5728" };
    }
    if (type === "r2") {
      if (!config4.r2Endpoint || !config4.r2Bucket || !config4.r2AccessKey || !config4.r2SecretKey) {
        set2.status = 400;
        return { error: "R2 \u914D\u7F6E\u4FE1\u606F\u4E0D\u5B8C\u6574" };
      }
    } else if (type === "onedrive") {
      if (!config4.oneDriveClientId || !config4.oneDriveTenantId || !clientSecret) {
        set2.status = 400;
        return { error: "OneDrive \u914D\u7F6E\u4FE1\u606F\u4E0D\u5B8C\u6574" };
      }
    } else if (type === "webdav") {
      if (!config4.webDavUrl || !config4.webDavUser || !config4.webDavPass) {
        set2.status = 400;
        return { error: "WebDAV \u914D\u7F6E\u4FE1\u606F\u4E0D\u5B8C\u6574" };
      }
    }
    const strategyId = crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}`;
    const now = Date.now();
    const strategyConfig = {
      ...config4,
      ...type === "onedrive" && clientSecret && { oneDriveClientSecret: clientSecret }
    };
    await db2.insert(storageStrategies).values({
      id: strategyId,
      name,
      type,
      config: JSON.stringify(strategyConfig),
      isActive: false,
      createdAt: now,
      updatedAt: now
    });
    logger3.database("INSERT", "storage_strategies");
    logger3.info(`\u5B58\u50A8\u7B56\u7565\u521B\u5EFA\u6210\u529F: ${name}`);
    return { message: "\u5B58\u50A8\u7B56\u7565\u521B\u5EFA\u6210\u529F", strategyId };
  } catch (error) {
    logger3.error("\u521B\u5EFA\u5B58\u50A8\u7B56\u7565\u5931\u8D25:", error);
    set2.status = 500;
    return { error: "\u521B\u5EFA\u5B58\u50A8\u7B56\u7565\u5931\u8D25" };
  }
}, {
  body: t.Object({
    name: t.String(),
    type: t.Union([t.Literal("local"), t.Literal("r2"), t.Literal("onedrive"), t.Literal("webdav")]),
    config: t.Object({
      r2Endpoint: t.Optional(t.String()),
      r2Bucket: t.Optional(t.String()),
      r2AccessKey: t.Optional(t.String()),
      r2SecretKey: t.Optional(t.String()),
      oneDriveClientId: t.Optional(t.String()),
      oneDriveTenantId: t.Optional(t.String()),
      webDavUrl: t.Optional(t.String()),
      webDavUser: t.Optional(t.String()),
      webDavPass: t.Optional(t.String())
    }),
    clientSecret: t.Optional(t.String())
  })
}).put("/strategies/:id", async (ctx) => {
  const { params, body, set: set2 } = ctx;
  try {
    const { id } = params;
    const { name, type, config: config4, clientSecret } = body;
    logger3.info(`\u66F4\u65B0\u5B58\u50A8\u7B56\u7565: ${id}`);
    const existingStrategy = await db2.select().from(storageStrategies).where(eq(storageStrategies.id, id)).get();
    if (!existingStrategy) {
      set2.status = 404;
      return { error: "\u5B58\u50A8\u7B56\u7565\u4E0D\u5B58\u5728" };
    }
    const duplicateStrategy = await db2.select().from(storageStrategies).where(and(eq(storageStrategies.name, name), eq(storageStrategies.id, id))).get();
    if (duplicateStrategy && duplicateStrategy.id !== id) {
      set2.status = 400;
      return { error: "\u7B56\u7565\u540D\u79F0\u5DF2\u5B58\u5728" };
    }
    if (type === "r2") {
      if (!config4.r2Endpoint || !config4.r2Bucket || !config4.r2AccessKey || !config4.r2SecretKey) {
        set2.status = 400;
        return { error: "R2 \u914D\u7F6E\u4FE1\u606F\u4E0D\u5B8C\u6574" };
      }
    } else if (type === "onedrive") {
      if (!config4.oneDriveClientId || !config4.oneDriveTenantId || !clientSecret) {
        set2.status = 400;
        return { error: "OneDrive \u914D\u7F6E\u4FE1\u606F\u4E0D\u5B8C\u6574" };
      }
    } else if (type === "webdav") {
      if (!config4.webDavUrl || !config4.webDavUser || !config4.webDavPass) {
        set2.status = 400;
        return { error: "WebDAV \u914D\u7F6E\u4FE1\u606F\u4E0D\u5B8C\u6574" };
      }
    }
    const strategyConfig = {
      ...config4,
      ...type === "onedrive" && clientSecret && { oneDriveClientSecret: clientSecret }
    };
    await db2.update(storageStrategies).set({
      name,
      type,
      config: JSON.stringify(strategyConfig),
      updatedAt: Date.now()
    }).where(eq(storageStrategies.id, id));
    logger3.database("UPDATE", "storage_strategies");
    logger3.info(`\u5B58\u50A8\u7B56\u7565\u66F4\u65B0\u6210\u529F: ${id}`);
    return { message: "\u5B58\u50A8\u7B56\u7565\u66F4\u65B0\u6210\u529F" };
  } catch (error) {
    logger3.error("\u66F4\u65B0\u5B58\u50A8\u7B56\u7565\u5931\u8D25:", error);
    set2.status = 500;
    return { error: "\u66F4\u65B0\u5B58\u50A8\u7B56\u7565\u5931\u8D25" };
  }
}, {
  body: t.Object({
    name: t.String(),
    type: t.Union([t.Literal("local"), t.Literal("r2"), t.Literal("onedrive"), t.Literal("webdav")]),
    config: t.Object({
      r2Endpoint: t.Optional(t.String()),
      r2Bucket: t.Optional(t.String()),
      r2AccessKey: t.Optional(t.String()),
      r2SecretKey: t.Optional(t.String()),
      oneDriveClientId: t.Optional(t.String()),
      oneDriveTenantId: t.Optional(t.String()),
      webDavUrl: t.Optional(t.String()),
      webDavUser: t.Optional(t.String()),
      webDavPass: t.Optional(t.String())
    }),
    clientSecret: t.Optional(t.String())
  })
}).delete("/strategies/:id", async (ctx) => {
  const { params, set: set2 } = ctx;
  try {
    const { id } = params;
    logger3.info(`\u5220\u9664\u5B58\u50A8\u7B56\u7565: ${id}`);
    const strategy = await db2.select().from(storageStrategies).where(eq(storageStrategies.id, id)).get();
    if (!strategy) {
      set2.status = 404;
      return { error: "\u5B58\u50A8\u7B56\u7565\u4E0D\u5B58\u5728" };
    }
    if (strategy.isActive) {
      set2.status = 400;
      return { error: "\u65E0\u6CD5\u5220\u9664\u6FC0\u6D3B\u7684\u5B58\u50A8\u7B56\u7565\uFF0C\u8BF7\u5148\u5207\u6362\u5230\u5176\u4ED6\u7B56\u7565" };
    }
    await db2.delete(storageStrategies).where(eq(storageStrategies.id, id));
    logger3.database("DELETE", "storage_strategies");
    logger3.info(`\u5B58\u50A8\u7B56\u7565\u5220\u9664\u6210\u529F: ${id}`);
    return { message: "\u5B58\u50A8\u7B56\u7565\u5220\u9664\u6210\u529F" };
  } catch (error) {
    logger3.error("\u5220\u9664\u5B58\u50A8\u7B56\u7565\u5931\u8D25:", error);
    set2.status = 500;
    return { error: "\u5220\u9664\u5B58\u50A8\u7B56\u7565\u5931\u8D25" };
  }
}).put("/strategies/:id/toggle", async (ctx) => {
  const { params, body, set: set2 } = ctx;
  try {
    const { id } = params;
    const { isActive } = body;
    logger3.info(`\u5207\u6362\u5B58\u50A8\u7B56\u7565\u72B6\u6001: ${id} -> ${isActive}`);
    const strategy = await db2.select().from(storageStrategies).where(eq(storageStrategies.id, id)).get();
    if (!strategy) {
      set2.status = 404;
      return { error: "\u5B58\u50A8\u7B56\u7565\u4E0D\u5B58\u5728" };
    }
    if (isActive) {
      await db2.update(storageStrategies).set({ isActive: false }).where(eq(storageStrategies.isActive, true));
    }
    await db2.update(storageStrategies).set({ isActive, updatedAt: Date.now() }).where(eq(storageStrategies.id, id));
    if (isActive) {
      try {
        const activeStrategy = JSON.parse(strategy.config);
        const existingConfig = await db2.select().from(storageConfig).get();
        const configData = {
          storageType: strategy.type,
          r2Endpoint: activeStrategy.r2Endpoint || "",
          r2AccessKey: activeStrategy.r2AccessKey || "",
          r2SecretKey: activeStrategy.r2SecretKey || "",
          r2Bucket: activeStrategy.r2Bucket || "",
          oneDriveClientId: activeStrategy.oneDriveClientId || "",
          oneDriveClientSecret: activeStrategy.oneDriveClientSecret || "",
          oneDriveTenantId: activeStrategy.oneDriveTenantId || "",
          oneDriveWebDavUrl: activeStrategy.webDavUrl || "",
          oneDriveWebDavUser: activeStrategy.webDavUser || "",
          oneDriveWebDavPass: activeStrategy.webDavPass || "",
          enableMixedMode: false,
          updatedAt: Date.now()
        };
        if (existingConfig) {
          await db2.update(storageConfig).set(configData).where(eq(storageConfig.id, 1));
        } else {
          await db2.insert(storageConfig).values({ id: 1, ...configData });
        }
        logger3.info(`\u5B58\u50A8\u914D\u7F6E\u5DF2\u540C\u6B65: ${strategy.type}`);
      } catch (dbError) {
        logger3.error("\u540C\u6B65\u5B58\u50A8\u914D\u7F6E\u5931\u8D25:", dbError);
      }
    }
    logger3.database("UPDATE", "storage_strategies");
    logger3.info(`\u5B58\u50A8\u7B56\u7565\u72B6\u6001\u5207\u6362\u6210\u529F: ${id}`);
    return { message: "\u5B58\u50A8\u7B56\u7565\u72B6\u6001\u5207\u6362\u6210\u529F" };
  } catch (error) {
    logger3.error("\u5207\u6362\u5B58\u50A8\u7B56\u7565\u72B6\u6001\u5931\u8D25:", error);
    set2.status = 500;
    return { error: "\u5207\u6362\u5B58\u50A8\u7B56\u7565\u72B6\u6001\u5931\u8D25" };
  }
}, {
  body: t.Object({ isActive: t.Boolean() })
});

// src/routes/storage/onedrive-auth.ts
init_db2();
init_schema();
init_logger2();
init_drizzle_orm();
init_onedrive();
var onedriveAuthRoutes = new Elysia().get("/onedrive/auth-url", async (ctx) => {
  const { query, set: set2 } = ctx;
  try {
    const { redirectUri } = query;
    if (!redirectUri) {
      set2.status = 400;
      return { error: "Missing redirectUri parameter" };
    }
    logger3.debug(`\u83B7\u53D6OneDrive\u8BA4\u8BC1URL: ${redirectUri}`);
    const config4 = await db2.select().from(storageConfig).get();
    if (!config4 || !config4.oneDriveClientId || !config4.oneDriveTenantId) {
      set2.status = 400;
      return { error: "OneDrive not configured" };
    }
    const oneDriveService = new OneDriveService({
      clientId: config4.oneDriveClientId,
      clientSecret: config4.oneDriveClientSecret || "",
      tenantId: config4.oneDriveTenantId
    });
    const authUrl = oneDriveService.getAuthUrl(redirectUri);
    logger3.info(`OneDrive\u8BA4\u8BC1URL\u751F\u6210\u6210\u529F`);
    return { authUrl };
  } catch (error) {
    logger3.error("\u83B7\u53D6OneDrive\u8BA4\u8BC1URL\u5931\u8D25:", error);
    set2.status = 500;
    return { error: "Failed to get OneDrive auth URL" };
  }
}, { query: t.Object({ redirectUri: t.String() }) }).post("/onedrive/callback", async (ctx) => {
  const { body, user, set: set2 } = ctx;
  try {
    const { code, redirectUri } = body;
    logger3.info(`\u5904\u7406OneDrive\u8BA4\u8BC1\u56DE\u8C03: \u7528\u6237 ${user.userId}`);
    const config4 = await db2.select().from(storageConfig).get();
    if (!config4 || !config4.oneDriveClientId || !config4.oneDriveTenantId) {
      set2.status = 400;
      return { error: "OneDrive not configured" };
    }
    const oneDriveService = new OneDriveService({
      clientId: config4.oneDriveClientId,
      clientSecret: config4.oneDriveClientSecret || "",
      tenantId: config4.oneDriveTenantId
    });
    const tokenData = await oneDriveService.getTokenFromCode(code, redirectUri);
    const existingAuth = await db2.select().from(oneDriveAuth).where(eq(oneDriveAuth.userId, user.userId)).get();
    const authId = existingAuth?.id || crypto.randomUUID?.() || `${Date.now()}`;
    const now = Date.now();
    if (existingAuth) {
      await db2.update(oneDriveAuth).set({
        accessToken: tokenData.accessToken,
        refreshToken: tokenData.refreshToken,
        expiresAt: tokenData.expiresAt,
        scope: tokenData.scope || "Files.ReadWrite.All",
        updatedAt: now
      }).where(eq(oneDriveAuth.id, authId));
    } else {
      await db2.insert(oneDriveAuth).values({
        id: authId,
        userId: user.userId,
        accessToken: tokenData.accessToken,
        refreshToken: tokenData.refreshToken,
        expiresAt: tokenData.expiresAt,
        scope: tokenData.scope || "Files.ReadWrite.All",
        createdAt: now,
        updatedAt: now
      });
    }
    logger3.database("UPSERT", "onedrive_auth");
    logger3.info(`OneDrive\u8BA4\u8BC1\u6210\u529F: \u7528\u6237 ${user.userId}`);
    return { message: "OneDrive authentication successful" };
  } catch (error) {
    logger3.error("OneDrive\u8BA4\u8BC1\u56DE\u8C03\u5904\u7406\u5931\u8D25:", error);
    set2.status = 500;
    return { error: "OneDrive authentication failed" };
  }
}, { body: t.Object({ code: t.String(), redirectUri: t.String() }) }).get("/onedrive/status", async (ctx) => {
  const { user } = ctx;
  try {
    logger3.debug(`\u68C0\u67E5OneDrive\u8BA4\u8BC1\u72B6\u6001: \u7528\u6237 ${user.userId}`);
    let auth = await db2.select().from(oneDriveAuth).where(eq(oneDriveAuth.userId, user.userId)).get();
    if (!auth) {
      return { connected: false, authenticated: false };
    }
    const now = Date.now();
    const refreshThresholdMs = 5 * 60 * 1000;
    let refreshed = false;
    try {
      const config4 = await db2.select().from(storageConfig).get();
      const shouldRefresh = auth.expiresAt <= now + refreshThresholdMs;
      if (shouldRefresh && config4?.oneDriveClientId) {
        const svc = new OneDriveService({
          clientId: config4.oneDriveClientId,
          clientSecret: config4.oneDriveClientSecret || "",
          tenantId: config4.oneDriveTenantId || "common"
        });
        const newTokens = await svc.refreshToken(auth.refreshToken);
        await db2.update(oneDriveAuth).set({
          accessToken: newTokens.accessToken,
          refreshToken: newTokens.refreshToken,
          expiresAt: newTokens.expiresAt,
          updatedAt: now
        }).where(eq(oneDriveAuth.id, auth.id));
        auth = { ...auth, accessToken: newTokens.accessToken, refreshToken: newTokens.refreshToken, expiresAt: newTokens.expiresAt, updatedAt: now };
        refreshed = true;
        logger3.info(`OneDrive \u8BBF\u95EE\u4EE4\u724C\u5DF2\u81EA\u52A8\u5237\u65B0: \u7528\u6237 ${user.userId}`);
      }
    } catch (e3) {
      logger3.warn("\u81EA\u52A8\u5237\u65B0OneDrive\u4EE4\u724C\u5931\u8D25:", e3);
    }
    const isExpiredNow = auth.expiresAt <= Date.now();
    if (isExpiredNow) {
      return { connected: false, authenticated: false, expiresAt: auth.expiresAt, scope: auth.scope, lastUpdated: auth.updatedAt, refreshed };
    }
    let storageInfo;
    try {
      const config4 = await db2.select().from(storageConfig).get();
      if (config4?.oneDriveClientId) {
        const svc = new OneDriveService({
          clientId: config4.oneDriveClientId,
          clientSecret: config4.oneDriveClientSecret || "",
          tenantId: config4.oneDriveTenantId || "common"
        });
        svc.setAccessToken(auth.accessToken);
        const drive = await svc.getDriveInfo();
        const quota = drive?.quota || {};
        const total = Number(quota.total || 0);
        const used = Number(quota.used || 0);
        const available = typeof quota.remaining === "number" ? Number(quota.remaining) : Math.max(total - used, 0);
        storageInfo = { total, used, available };
        logger3.info(`OneDrive \u5B58\u50A8\u4FE1\u606F: total=${total}, used=${used}, available=${available}`);
      }
    } catch (e3) {
      logger3.warn("\u83B7\u53D6OneDrive\u5B58\u50A8\u4FE1\u606F\u5931\u8D25:", e3);
    }
    return { connected: true, authenticated: true, expiresAt: auth.expiresAt, scope: auth.scope, lastUpdated: auth.updatedAt, refreshed, storageInfo };
  } catch (error) {
    logger3.error("\u68C0\u67E5OneDrive\u8BA4\u8BC1\u72B6\u6001\u5931\u8D25:", error);
    return { authenticated: false };
  }
});

// src/routes/storage/onedrive-mounts.ts
init_db2();
