var storageRoutes = new Elysia({ prefix: "/storage" }).use(jwt({
  name: "jwt",
  secret: process.env.JWT_SECRET || "your-secret-key"
})).use(bearer()).derive(async ({ jwt: jwt2, bearer: bearer2, set: set2 }) => {
  if (!bearer2) {
    set2.status = 401;
    throw new Error("No token provided");
  }
  const payload = await jwt2.verify(bearer2);
  if (!payload || payload.role !== "admin") {
    set2.status = 403;
    throw new Error("Admin access required");
  }
  return { user: payload };
}).use(configRoutes).use(strategiesRoutes).use(onedriveAuthRoutes).use(onedriveMountRoutes).use(r2Routes);

